import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.D_ZOUi6P.js";const u=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"development/testing.md","filePath":"development/testing.md","lastUpdated":1793227266000}'),i={name:"development/testing.md"};function o(r,e,c,d,l,p){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><blockquote><p><strong>Note for developing on macOS</strong>: Docker typically runs inside a Linux VM and the socket may not be at the standard <code>/var/run/docker.sock</code> path. The test tooling automatically searches common non-standard socket locations when the standard path is absent. If auto-detection doesn&#39;t find your socket, set the <code>DOCKER_HOST</code> environment variable.</p></blockquote><p>The Saluki testing strategy consists of four main pillars:</p><ol><li>Unit Tests (Rust/cargo)</li><li>Correctness Tests (panoramic)</li><li>Integration Tests (panoramic)</li><li>Performance Tests (SMP)</li></ol><p>Alongside these, we use fuzzing, Loom and Miri for concurrency and memory-model correctness, and Antithesis for fault-injected equivalence testing.</p><h2 id="unit-tests" tabindex="-1">Unit tests <a class="header-anchor" href="#unit-tests" aria-label="Permalink to &quot;Unit tests&quot;">​</a></h2><p>These are found throughout the Rust codebase as you would expect. You can run them with <code>cargo test</code> or you can use <code>make test</code> which will run them with <code>cargo nextest</code> for more parallelization. Platform-specific unit tests should be skipped or compiled-out for platforms they&#39;re incompatible with. For conventions on test naming, table-driven tests, shared fixtures, and assertion density, see <a href="./testing-patterns">Testing patterns</a>.</p><p>CI: <code>.gitlab/test.yml</code>—runs on both Linux (amd64/arm64) and macOS (amd64/arm64).</p><h2 id="correctness-tests-panoramic" tabindex="-1">Correctness tests (panoramic) <a class="header-anchor" href="#correctness-tests-panoramic" aria-label="Permalink to &quot;Correctness tests (panoramic)&quot;">​</a></h2><p>These tests serve to answer the question: <em>Does ADP produce the same output as the Datadog Agent for a given workload?</em></p><p>To answer this question, a correctness test runs ADP and the Datadog Agent side-by-side in containers and compares their output for a given input. The output comparison is semantic, not a simple byte-by-byte comparison, thus heuristics are used to assert correctness.</p><p><strong>Terminology Note:</strong> Correctness tests <em><strong>are integration tests</strong></em> in the sense that they run the entire system. However, in our repository, <em>integration tests</em> refer to a specific set of smoke tests <a href="#integration-tests-panoramic">below</a>.</p><p>Correctness test cases are specified by YAML configuration files found in <code>test/correctness/cases</code>.</p><h3 id="binaries-and-program-flow" tabindex="-1">Binaries and program flow <a class="header-anchor" href="#binaries-and-program-flow" aria-label="Permalink to &quot;Binaries and program flow&quot;">​</a></h3><p>All binaries live under <code>bin/correctness/</code>:</p><table tabindex="0"><thead><tr><th>Binary</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>panoramic</strong></td><td>Unified test runner for both correctness and integration tests.</td></tr><tr><td><strong>millstone</strong></td><td>Deterministic load generator.</td></tr><tr><td><strong>datadog-intake</strong></td><td>Mock Datadog API: receives test output</td></tr><tr><td><strong>airlock</strong></td><td>Library for running containers in isolated groups.</td></tr></tbody></table><p>Test case configs live in <code>test/correctness/cases/</code> (for example, <code>test/correctness/cases/dsd-plain/config.yaml</code>).</p><h3 id="program-flow" tabindex="-1">Program flow <a class="header-anchor" href="#program-flow" aria-label="Permalink to &quot;Program flow&quot;">​</a></h3><p><strong>panoramic</strong> is the entry-point for running a test. When given a correctness test config, it orchestrates the containers using the <code>airlock</code> library (which talks to containerd via gRPC) and asserts the correctness of the output. It:</p><ul><li>reads the test configuration files</li><li>starts two sets of containers <ul><li><code>millstone</code> -&gt; ADP -&gt; <code>datadog-intake</code></li><li><code>millstone</code> -&gt; Datadog Agent -&gt; <code>datadog-intake</code></li></ul></li><li>takes the output from <code>datadog-intake</code> and asserts that ADP and Datadog Agent behavior were equivalent</li></ul><h3 id="running" tabindex="-1">Running <a class="header-anchor" href="#running" aria-label="Permalink to &quot;Running&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run all correctness tests:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-correctness</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run a single test case:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-correctness-case</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CASE=dsd-plain</span></span></code></pre></div><p>The <code>test-correctness</code> target handles building all of the necessary prerequisites -- <code>millstone</code>, <code>datadog-intake</code>, <code>panoramic</code>, the bundled Agent/ADP image, and so on -- before running the test cases.</p><p>Correctness tests are run in the <code>e2e</code> stage in CI (<code>.gitlab/e2e.yml</code>).</p><h2 id="integration-tests-panoramic" tabindex="-1">Integration tests (panoramic) <a class="header-anchor" href="#integration-tests-panoramic" aria-label="Permalink to &quot;Integration tests (panoramic)&quot;">​</a></h2><p>Integration tests run a containerized ADP instance and assert high-level invariants: process stability, expected log output, port availability, exit behavior. They catch regressions from enabling new features or settings that cause crashes or early exits. They don&#39;t test output correctness. This type of test is often known as a &quot;smoke test.&quot; For integration tests that check system output, see <a href="#correctness-tests-panoramic">correctness tests</a> above.</p><h3 id="running-1" tabindex="-1">Running <a class="header-anchor" href="#running-1" aria-label="Permalink to &quot;Running&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # build images + run all</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test-integration-quick</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # skip image builds</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list-integration-tests</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # list available tests</span></span></code></pre></div><h3 id="test-case-config" tabindex="-1">Test case config <a class="header-anchor" href="#test-case-config" aria-label="Permalink to &quot;Test case config&quot;">​</a></h3><p>Test cases live in <code>test/integration/cases/</code> as <code>config.yaml</code> files. The runner is <strong>panoramic</strong> (<code>bin/correctness/panoramic/</code>).</p><p>Each test defines a container and a list of high-level assertions. Assertions run sequentially by default but can also be configured to run in <code>parallel</code>.</p><p>CI: <code>.gitlab/e2e.yml</code>—same file as correctness, <code>e2e</code> stage, 10 min timeout, retry 2.</p><h3 id="step-deadlines" tabindex="-1">Step deadlines <a class="header-anchor" href="#step-deadlines" aria-label="Permalink to &quot;Step deadlines&quot;">​</a></h3><p>Each step uses its <code>timeout</code>, <code>duration</code>, or <code>during</code> as its budget. The <code>dogstatsd_replay</code> action uses a whole-action budget of <code>4 × timeout + capture_duration + 50ms</code>. The driver allows 10 seconds beyond that budget for the step to report its result, then stops it as <code>errored</code>. This makes the test a harness error (exit code 2), unless a parallel member failed. Case timeout or run cancellation interrupts unfinished steps and preserves completed results.</p><h2 id="panoramic-cli-and-environment" tabindex="-1">Panoramic CLI and environment <a class="header-anchor" href="#panoramic-cli-and-environment" aria-label="Permalink to &quot;Panoramic CLI and environment&quot;">​</a></h2><p>Both suites run through the same <code>panoramic</code> binary.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> panoramic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>The <code>panoramic</code> skill walks LLM agents through choosing and running a suite non-interactively.</p><h3 id="reading-panoramic-results" tabindex="-1">Reading panoramic results <a class="header-anchor" href="#reading-panoramic-results" aria-label="Permalink to &quot;Reading panoramic results&quot;">​</a></h3><p>The Make targets write artifacts beneath <code>target/test-output/panoramic/</code> by default. Set <code>SALUKI_TEST_OUTPUT_DIR</code> to relocate the shared test-output root, or <code>PANORAMIC_LOG_DIR</code> to override the location for panoramic only. Each run creates a timestamped <code>panoramic-*</code> directory beneath the base, and stdout and <code>run.json</code> identify the directory for a run. <code>make clean-test-logs</code> deletes the panoramic directory, and <code>make clean</code> includes that target.</p><p>Exit codes distinguish the run-level result:</p><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>Every test passed</td></tr><tr><td>1</td><td>At least one assertion failed</td></tr><tr><td>2</td><td>Harness error, timeout, or interrupted run</td></tr><tr><td>3</td><td>The selection matched no tests</td></tr></tbody></table><p>For code 2, investigate the harness or environment before assertion differences.</p><p>Check <code>run.json</code> first: it&#39;s updated during execution, so passing entries don&#39;t prove the run finished. Inspect completeness before individual results, and treat unknown states, outcomes, or statuses as non-passing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{state, interrupted_reason, running, not_run}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.tests[] | select(.outcome != &quot;passed&quot; or (.issues | length) &gt; 0) | &quot;\\(.name) \\(.outcome) \\(.log_dir)&quot;&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run.json</span></span></code></pre></div><p>Follow the selected tests&#39; <code>log_dir</code> to <code>result.json</code>. Use <code>outcome</code> for the test result and <code>assertions[].status</code> for each step. Check <code>issues</code> even on passes; they don&#39;t change <code>outcome</code>. Open reported artifact paths and <code>diagnostic_lines</code> sources for context and uncapped details.</p><p>For semantics, read <code>RunReport</code>, <code>TestReport</code>, and <code>AssertionReport</code> in <code>bin/correctness/panoramic/src/machine_output.rs</code> and follow their types. Step-to-outcome rules are in <code>TestResult::from_steps</code> in <code>reporter.rs</code>. Check <code>schema_version</code> and <code>run.json</code>&#39;s <code>build_revision</code> when reports differ from the working tree.</p><p>On Unix, send SIGINT or SIGTERM to stop a run with cleanup. A second signal may leave containers behind.</p><h3 id="reading-traffic-artifacts" tabindex="-1">Reading traffic artifacts <a class="header-anchor" href="#reading-traffic-artifacts" aria-label="Permalink to &quot;Reading traffic artifacts&quot;">​</a></h3><p>Traffic captures live under <code>&lt;log_dir&gt;/traffic/</code>. Start with <code>traffic/manifest.json</code>: it lists each capture, whether its file is still on disk, and why any capture is missing. Take file names from the manifest rather than guessing them. Captures are zstd-compressed JSON Lines:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;(.input // empty), .decoded[] | select(.file.present) | .file.name&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> traffic/manifest.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zstd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> traffic/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span></span></code></pre></div><p>The module docs in <code>bin/correctness/panoramic/src/traffic.rs</code> explain each artifact, its retention, and record ordering. For intake sidecar captures, see &quot;Intake artifacts&quot; in <code>test/integration/README.md</code>.</p><h2 id="benchmark-tests-single-machine-performance-smp" tabindex="-1">Benchmark tests: Single Machine Performance (SMP) <a class="header-anchor" href="#benchmark-tests-single-machine-performance-smp" aria-label="Permalink to &quot;Benchmark tests: Single Machine Performance (SMP)&quot;">​</a></h2><p>SMP is a system that runs on internal, dedicated infrastructure to check the Agent for performance regressions. It runs experiments across multiple replicates with statistical analysis and posts reports to PRs. Maps to the <code>benchmark</code> stage in GitLab CI (<code>.gitlab/benchmark.yml</code>).</p><p>Each experiment pairs a <strong>target</strong> (ADP container) with <strong>Lading</strong> (deterministic load generator). Lading sends payloads (DogStatsD, OTLP, logs, etc.) at configured rates using seeded generators for reproducibility. SMP measures CPU, memory, throughput—not output correctness.</p><h3 id="experiments" tabindex="-1">Experiments <a class="header-anchor" href="#experiments" aria-label="Permalink to &quot;Experiments&quot;">​</a></h3><p>Defined in <code>test/smp/regression/adp/experiments.yaml</code>. Run <code>make generate-smp-experiments</code> to generate per-case configs into two suites: <code>test/smp/regression/adp/quality-gates/</code> (experiments with <code>checks:</code> bounds) and <code>test/smp/regression/adp/full/</code> (all experiments). Each case gets an <code>experiment.yaml</code> (target config) and <code>lading/lading.yaml</code> (load config). See <code>test/smp/README.md</code> for the suite model.</p><p>PRs gate only on the quality-gates suite, comparing the branch against the merge-base of main—&quot;has your change regressed or improved against the bounds?&quot; The full suite runs nightly on <code>main</code> (date-anchored against the previous nightly, reported to Slack) and on-demand as a manual job on a PR; it is for long-term trend analysis and does not gate.</p><p>You can run experiments locally with <code>smp local-run</code> to debug experiment configs without waiting for CI (single replicate, no statistical analysis). This is mainly useful when iterating on a new or broken experiment—for normal development, lean on CI.</p><h2 id="fuzzing" tabindex="-1">Fuzzing <a class="header-anchor" href="#fuzzing" aria-label="Permalink to &quot;Fuzzing&quot;">​</a></h2><p>We aren&#39;t doing a lot with fuzzing right now, but what we&#39;ve uses <code>cargo-fuzz</code> and operates at the function-level. More fuzzing coverage will likely come in the future.</p><h2 id="loom-and-miri-testing" tabindex="-1">Loom and Miri testing <a class="header-anchor" href="#loom-and-miri-testing" aria-label="Permalink to &quot;Loom and Miri testing&quot;">​</a></h2><p>Loom and Miri target concurrency and memory-model correctness rather than business logic. <strong>Loom</strong> exhaustively explores how concurrent operations can interleave, to catch ordering bugs that are hard to hit through normal test runs. Run it with <code>make test-loom</code>. <strong>Miri</strong> runs tests under an interpreter that catches undefined behavior—data races, use-after-free, invalid memory access—that a normal test run wouldn&#39;t detect. Run it with <code>make test-miri</code>.</p><h2 id="antithesis" tabindex="-1">Antithesis <a class="header-anchor" href="#antithesis" aria-label="Permalink to &quot;Antithesis&quot;">​</a></h2><p><a href="https://antithesis.com/" target="_blank" rel="noreferrer">Antithesis</a> runs ADP under deterministic simulation with injected faults. Our focus is on establishing that ADP and the Datadog Agent&#39;s DogStatsD behave equivalently: if ADP replaces the Agent&#39;s DogStatsD server, users shouldn&#39;t notice shifts in their telemetry. Better operational behavior is an acceptable deviation.</p><p>This is separate from the panoramic correctness tests, which compare outputs for fixed workloads without fault injection. The harness and scenarios live under <code>test/antithesis/</code>, and <code>test/antithesis/AGENTS.md</code> describes how agents drive runs there.</p><h2 id="directory-index" tabindex="-1">Directory index <a class="header-anchor" href="#directory-index" aria-label="Permalink to &quot;Directory index&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.gitlab/</span></span>
<span class="line"><span>├── test.yml               unit tests</span></span>
<span class="line"><span>├── e2e.yml                correctness + integration</span></span>
<span class="line"><span>├── benchmark.yml          SMP benchmarks</span></span>
<span class="line"><span>└── fuzz.yml               fuzz testing</span></span>
<span class="line"><span></span></span>
<span class="line"><span># custom test tooling</span></span>
<span class="line"><span>bin/correctness/</span></span>
<span class="line"><span>├── panoramic/             : unified test runner (correctness + integration)</span></span>
<span class="line"><span>├── millstone/             : load generator</span></span>
<span class="line"><span>├── datadog-intake/        : mock Datadog API</span></span>
<span class="line"><span>├── airlock/               : container isolation lib</span></span>
<span class="line"><span>└── stele/                 : telemetry data types</span></span>
<span class="line"><span></span></span>
<span class="line"><span># actual test cases</span></span>
<span class="line"><span>test/</span></span>
<span class="line"><span>├── correctness/           : correctness test configs</span></span>
<span class="line"><span>├── antithesis/            : antithesis harness and scenarios</span></span>
<span class="line"><span>├── integration/           : integration test configs</span></span>
<span class="line"><span>└── smp/                   : smp experiments</span></span></code></pre></div>`,68)])])}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
